cases.source:
language "EAL/3"

environment lab {
  require "site" == "bench"
}

tool collector {
  version "1"
}

evidence primary_data {
  tool collector
  kind test
  environment lab
  max_age 60
  require "ok" == true
}

evidence probe_data {
  tool collector
  kind test
  environment lab
  max_age 60
  require "ok" == true
}

evidence gap_data {
  tool collector
  kind test
  environment lab
  max_age 60
  require "ok" == true
}

evidence calibration_data {
  tool collector
  kind test
  environment lab
  max_age 60
  require "ok" == true
}

reasoning authored {
  method "structured/1"
  rationale "Bounded measured route."
}

claim run_passes {
  statement "This run meets the specified result."
  environment lab
}

claim reportable {
  statement "This run may be reported."
  environment lab
}

argument primary_route = [evidence primary_data, assumptions calibration] via authored => run_passes

argument probe_route = [evidence probe_data] via authored => run_passes

argument reporting_route = [premises run_passes] via authored => reportable

assumption calibration {
  statement "Calibration is applicable to this run."
  environment lab
  validate calibration_data
}

